function Create-Article {
    param($FileName, $Title, $Subtitle, $Image, $Text, $Fact)
    
    $html = @"
<!DOCTYPE html>
<html lang="ru">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>$Title | Российская космонавтика</title>
  <link rel="stylesheet" href="../css/style.css">
</head>
<body>
  <canvas id="star-canvas"></canvas>
  <header>
    <a href="../index.html" class="logo">← На главную</a>
    <nav>
      <a href="../pages/timeline.html">Лента времени</a>
      <a href="../pages/heroes.html">Личности</a>
      <a href="../pages/device.html">Техника</a>
      <a href="../pages/quiz.html">Квиз</a>
      <a href="../pages/rocket.html">Игра</a>
    </nav>
  </header>
  <main>
    <article style="max-width: 900px; margin: 0 auto; background: var(--card-bg); padding: 40px; border-radius: 20px; border: 1px solid var(--border); backdrop-filter: blur(10px);">
      <h1>$Title</h1>
      <p style="color: var(--accent); font-size: 1.2rem; font-weight: 500;">$Subtitle</p>
      <img src="../img/$Image" alt="$Title" style="display: block; max-width: 100%; max-height: 600px; width: auto; height: auto; margin: 30px auto; border-radius: 12px; border: 1px solid var(--border);">
      $Text
      <div style="background: rgba(255, 183, 3, 0.1); padding: 24px; border-left: 4px solid var(--accent); border-radius: 8px; margin-top: 40px;">
        <h3 style="margin-top: 0; color: var(--accent);">А ты знал?</h3>
        <p style="margin-bottom: 0;">$Fact</p>
      </div>
    </article>
  </main>
  <footer>
    <p>Учебный проект. Источники информации: <a href="https://www.roscosmos.ru/" target="_blank" rel="noopener noreferrer">Госкорпорация «Роскосмос»</a> и <a href="https://commons.wikimedia.org/" target="_blank" rel="noopener noreferrer">Wikimedia Commons</a>.</p>
  </footer>
  <script src="../js/stars.js"></script>
</body>
</html>
"@
    $html | Out-File -FilePath "articles\$FileName" -Encoding utf8
    Write-Host "Создан: $FileName"
}

Create-Article -FileName "titov.html" -Title "Герман Титов" -Subtitle "Первый человек, проведший в космосе более суток." -Image "titov.jpg" -Text "<h2>Самый молодой космонавт</h2><p>6 августа 1961 года Герман Титов отправился в космос на корабле «Восток-2». На момент старта ему было всего 25 лет, и он до сих пор остается самым молодым человеком, побывавшим на орбите.</p><h2>Сутки на орбите</h2><p>Его полёт длился 1 сутки 1 час и 18 минут. Это было огромное достижение: Титов доказал, что человек может жить и работать в невесомости длительное время. За это время он сделал 17 витков вокруг Земли и пролетел более 700 000 километров.</p>" -Fact "Титов был первым, кто пообедал в космосе. В его рацион входили супы, мясные консервы и даже черный хлеб."

Create-Article -FileName "nikolaev.html" -Title "Андриян Николаев" -Subtitle "Участник первого в мире группового полёта двух пилотируемых кораблей." -Image "nikolaev.jpg" -Text "<h2>Космическая дружба</h2><p>С 11 по 15 августа 1962 года Андриян Николаев пилотировал корабль «Восток-3». В это же время на орбите находился «Восток-4» под управлением Павла Поповича. Они летали рядом, и это был первый в мире групповой полёт.</p><h2>Рекорд длительности</h2><p>Полёт Николаева длился почти 4 суток. Космонавты установили новый рекорд по времени пребывания в космосе и впервые провели сеанс связи между двумя кораблями.</p>" -Fact "Андриян Николаев был женат на первой женщине-космонавте Валентине Терешковой. У них родилась дочь Елена."

Create-Article -FileName "popovich.html" -Title "Павел Попович" -Subtitle "Второй участник первого группового космического полёта." -Image "popovich.jpg" -Text "<h2>Полёт в паре</h2><p>12 августа 1962 года Павел Попович стартовал на корабле «Восток-4». Он присоединился к Андрияну Николаеву на орбите. Корабли подлетели друг к другу на расстояние до 5 километров.</p><h2>Ручное управление</h2><p>Во время полёта Попович впервые в истории выполнил ручное ориентирование корабля в космосе. Он также провел первые эксперименты по наблюдению за Землей.</p>" -Fact "Позывной Павла Поповича был «Беркут». После полёта он стал знаменитым на весь мир и часто ездил с лекциями за границу."

Create-Article -FileName "komarov.html" -Title "Владимир Комаров" -Subtitle "Командир первого в мире многоместного корабля и первый космонавт, побывавший на орбите дважды." -Image "komarov.jpg" -Text "<h2>Первый многоместный корабль</h2><p>12 октября 1964 года Владимир Комаров командовал кораблём «Восход». Впервые в истории в космос полетел экипаж из трёх человек — без скафандров, в обычных спортивных костюмах. Полёт длился всего 24 часа.</p><h2>Трагический полёт</h2><p>В 1967 году Комаров отправился в свой второй полёт на новом корабле «Союз-1». К сожалению, полёт закончился трагедией: при возвращении на Землю парашютная система не сработала, и спускаемый аппарат разбился. Владимир Комаров стал первым космонавтом, погибшим во время полёта.</p>" -Fact "Комаров был настолько опытным инженером и лётчиком, что даже во время падения корабля до последней секунды пытался исправить ситуацию и передавал данные на Землю."

Create-Article -FileName "krikalev.html" -Title "Сергей Крикалёв" -Subtitle "Первый российский космонавт, совершивший полёт на американском шаттле." -Image "krikalev.jpg" -Text "<h2>Мост между Россией и США</h2><p>В 1994 году Сергей Крикалёв стал первым российским космонавтом, который отправился на орбиту на американском космическом корабле «Дискавери». Это стало важным шагом в совместных международных программах.</p><h2>Человек, который «застрял» в космосе</h2><p>Самый знаменитый полёт Крикалёва начался в 1991 году, когда он отправился на станцию «Мир». Пока он был на орбите, СССР распался. Ему пришлось провести в космосе почти год, прежде чем за ним прилетели. Всего же за 6 полётов он провёл в космосе 803 дня.</p>" -Fact "Его рекорд по суммарному времени пребывания в космосе держался целых 10 лет (с 2005 по 2015 год), пока его не побил другой космонавт."

Create-Article -FileName "savitskaya.html" -Title "Светлана Савицкая" -Subtitle "Первая в мире женщина, вышедшая в открытый космос." -Image "savitskaya.jpg" -Text "<h2>Дорога в космос</h2><p>Светлана Савицкая была не только космонавтом, но и летчиком-испытателем. В 1982 году она совершила свой первый полёт на станцию «Салют-7».</p><h2>Выход в открытый космос</h2><p>25 июля 1984 года во время второго полёта Светлана Савицкая стала первой в истории женщиной, которая вышла в открытый космос. Она провела вне станции 3 часа 35 минут, выполняя сложные инженерные работы.</p>" -Fact "Именно Савицкая во время своего выхода в космос впервые провела уникальный эксперимент: она резала и сваривала металл в условиях невесомости с помощью специального универсального инструмента."

Create-Article -FileName "kondakova.html" -Title "Елена Кондакова" -Subtitle "Первая женщина, совершившая длительный (почти полугодовой) полёт." -Image "kondakova.jpg" -Text "<h2>Испытание длиною в полгода</h2><p>В 1994–1995 годах Елена Кондакова провела на орбитальной станции «Мир» 169 суток. Она стала первой женщиной, которая совершила столь длительный космический полёт, доказав, что женский организм справляется с долгим пребыванием в невесомости не хуже мужского.</p><h2>На американском шаттле</h2><p>Свой второй полёт Кондакова совершила в 1997 году на борту американского корабля «Атлантис» (миссия STS-84). Она стала первой и пока единственной россиянкой, побывавшей на шаттле.</p>" -Fact "Кондакова — первая женщина, награждённая медалью «Золотая Звезда» Героя Российской Федерации (а не Советского Союза, как ее предшественницы)."

Create-Article -FileName "serova.html" -Title "Елена Серова" -Subtitle "Первая россиянка, работавшая на борту Международной космической станции." -Image "serova.jpg" -Text "<h2>Космический полёт длиною в 170 дней</h2><p>В сентябре 2014 года Елена Серова отправилась на МКС в составе экипажа корабля «Союз ТМА-14М». Она провела на орбите около 170 суток, выполняя научные эксперименты и работы по обслуживанию станции.</p><h2>Новое поколение</h2><p>До неё из российских женщин в космосе бывали только Валентина Терешкова и Елена Кондакова. Серова стала четвертой женщиной-космонавтом в отечественной истории.</p>" -Fact "Елена Серова была удостоена звания Героя Российской Федерации. Она активно занимается популяризацией космонавтики и часто встречается со школьниками."

Create-Article -FileName "polyakov.html" -Title "Валерий Поляков" -Subtitle "Совершил самый длительный полёт в истории космонавтики." -Image "polyakov.jpg" -Text "<h2>Рекорд, который не побит до сих пор</h2><p>С января 1994 по март 1995 года Валерий Поляков провел на орбитальной станции «Мир» 437 суток (почти 14 месяцев). Это абсолютный рекорд по длительности одного космического полёта.</p><h2>Человек-эксперимент</h2><p>Поляков был не просто космонавтом, но и врачом-исследователем. Его полёт стал грандиозным научным экспериментом, доказавшим, что человеческий организм способен выдержать длительное пребывание в космосе. Это открытие стало ключевым для подготовки будущих полётов на Марс.</p>" -Fact "За время своего рекордного полёта Поляков совершил один выход в открытый космос."

Create-Article -FileName "padalka.html" -Title "Геннадий Падалка" -Subtitle "Абсолютный рекордсмен по суммарному времени пребывания в космосе." -Image "padalka.jpg" -Text "<h2>878 суток на орбите</h2><p>За свою карьеру Геннадий Падалка совершил 5 космических полётов. Суммарно он провёл на орбите 878 суток (почти 2,5 года). Это абсолютный мировой рекорд среди всех космонавтов и астронавтов.</p><h2>Командир МКС</h2><p>Падалка был командиром как на станции «Мир», так и на Международной космической станции (МКС). Он совершил 10 выходов в открытый космос, проведя за бортом станции более 38 часов.</p>" -Fact "Свой последний, пятый полёт Падалка совершил в 2015 году, когда ему было уже 57 лет."

Create-Article -FileName "dobrovolsky.html" -Title "Георгий Добровольский" -Subtitle "Командир первого экипажа первой в мире орбитальной станции «Салют»." -Image "dobrovolsky.jpg" -Text "<h2>Первый экипаж «Салюта»</h2><p>В июне 1971 года Георгий Добровольский командовал кораблём «Союз-11». Его экипаж должен был стать первой экспедицией на первую в мире орбитальную станцию «Салют-1». Они успешно состыковались со станцией и провели на ней 23 дня.</p><h2>Трагическое возвращение</h2><p>При возвращении на Землю на этапе спуска произошла разгерметизация спускаемого аппарата. Экипаж погиб за несколько минут до приземления. Георгий Добровольский посмертно был удостоен звания Героя Советского Союза.</p>" -Fact "Изначально Добровольский был дублёром, но из-за болезни основного командира экипажа был назначен на полёт всего за несколько дней до старта."

Create-Article -FileName "volkov.html" -Title "Владислав Волков" -Subtitle "Бортинженер первого экипажа станции «Салют» и дважды Герой Советского Союза." -Image "volkov.jpg" -Text "<h2>Два полёта</h2><p>Свой первый полёт Владислав Волков совершил в 1969 году на корабле «Союз-7». Это был групповой полёт трех кораблей. В 1971 году он отправился во вторую экспедицию на станцию «Салют-1» в составе экипажа «Союза-11».</p><h2>Посмертная награда</h2><p>Владислав Волков погиб вместе со своими товарищами при разгерметизации спускаемого аппарата. За проявленное мужество он был посмертно награждён второй медалью «Золотая Звезда» Героя Советского Союза.</p>" -Fact "Волков был не только космонавтом, но и талантливым спортсменом — он увлекался парашютным спортом и совершил более 100 прыжков."

Create-Article -FileName "patsaev.html" -Title "Виктор Пацаев" -Subtitle "Первый в мире астроном, работавший за пределами земной атмосферы." -Image "patsaev.jpg" -Text "<h2>Астроном на орбите</h2><p>Виктор Пацаев был инженером-исследователем и астрономом. В 1971 году он вошел в состав экипажа «Союза-11». На борту станции «Салют-1» он проводил уникальные астрономические наблюдения, став первым ученым-астрономом в космосе.</p><h2>Трагедия «Союза-11»</h2><p>Жизнь Пацаева трагически оборвалась при возвращении на Землю из-за разгерметизации спускаемого аппарата. За свой подвиг он был посмертно удостоен звания Героя Советского Союза.</p>" -Fact "Именем Виктора Пацаева назван кратер на обратной стороне Луны."

Write-Host "Все файлы успешно созданы!" -ForegroundColor Green